"use client";

import * as React from "react";
import { CheckIcon, ChevronsUpDownIcon } from "lucide-react";
import { buttonVariants } from "@/components/ui/button";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "cn";

export type ComboboxOption = { value: string; label: string; disabled?: boolean };

export function Combobox(props: { options: ComboboxOption[]; value?: string; onValueChange?: (value: string) => void; placeholder?: string; searchPlaceholder?: string; emptyMessage?: string; className?: string }) {
  const { options, value, onValueChange, placeholder = "Choose an option", searchPlaceholder = "Search options", emptyMessage = "No option found.", className } = props;
  const controlled = Object.prototype.hasOwnProperty.call(props, "value");
  const [open, setOpen] = React.useState(false);
  const [internalValue, setInternalValue] = React.useState(value ?? "");
  const selectedValue = controlled ? value : internalValue;
  const selected = options.find((option) => option.value === selectedValue);

  function select(nextValue: string) {
    if (!controlled) setInternalValue(nextValue);
    onValueChange?.(nextValue);
    setOpen(false);
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger data-slot="button" data-variant="outline" data-size="default" role="combobox" aria-expanded={open} className={cn(buttonVariants({ variant: "outline" }), "justify-between", className)}>
        {selected?.label ?? placeholder}
        <ChevronsUpDownIcon className="opacity-50" />
      </PopoverTrigger>
      <PopoverContent className="w-[var(--radix-popover-trigger-width,var(--anchor-width))] p-0">
        <Command>
          <CommandInput placeholder={searchPlaceholder} />
          <CommandList>
            <CommandEmpty>{emptyMessage}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => (
                <CommandItem key={option.value} value={option.label} disabled={option.disabled} onSelect={() => select(option.value)}>
                  {option.label}
                  <CheckIcon className={cn("ml-auto", selectedValue === option.value ? "opacity-100" : "opacity-0")} />
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import * as React from "react";
import { ArrowDownIcon, ArrowUpDownIcon, ArrowUpIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

export type DataTableColumn<Row> = {
  key: keyof Row & string;
  label: string;
  align?: "left" | "right";
  sortable?: boolean;
  render?: (value: Row[keyof Row], row: Row) => React.ReactNode;
};

export function DataTable<Row extends Record<string, unknown>>({ rows, columns, getRowId, emptyMessage = "No results." }: { rows: Row[]; columns: DataTableColumn<Row>[]; getRowId: (row: Row) => React.Key; emptyMessage?: string }) {
  const [sort, setSort] = React.useState<{ key: keyof Row & string; direction: "ascending" | "descending" }>();
  const sortedRows = React.useMemo(() => {
    if (!sort) return rows;
    return [...rows].sort((left, right) => {
      const a = left[sort.key];
      const b = right[sort.key];
      const result = String(a ?? "").localeCompare(String(b ?? ""), undefined, { numeric: true });
      return sort.direction === "ascending" ? result : result * -1;
    });
  }, [rows, sort]);

  function changeSort(key: keyof Row & string) {
    setSort((current) => current?.key === key && current.direction === "ascending" ? { key, direction: "descending" } : { key, direction: "ascending" });
  }

  return (
    <Table>
      <TableHeader>
        <TableRow>{columns.map((column) => <TableHead key={column.key} className={column.align === "right" ? "text-right" : undefined}>{column.sortable ? <Button variant="ghost" size="sm" onClick={() => changeSort(column.key)} aria-label={`Sort by ${column.label}`}>{column.label}{sort?.key !== column.key ? <ArrowUpDownIcon /> : sort.direction === "ascending" ? <ArrowUpIcon /> : <ArrowDownIcon />}</Button> : column.label}</TableHead>)}</TableRow>
      </TableHeader>
      <TableBody>
        {sortedRows.length ? sortedRows.map((row) => <TableRow key={getRowId(row)}>{columns.map((column) => <TableCell key={column.key} className={column.align === "right" ? "text-right" : undefined}>{column.render ? column.render(row[column.key], row) : String(row[column.key] ?? "")}</TableCell>)}</TableRow>) : <TableRow><TableCell colSpan={columns.length} className="h-24 text-center text-muted-foreground">{emptyMessage}</TableCell></TableRow>}
      </TableBody>
    </Table>
  );
}

"use client";

import * as React from "react";
import { CalendarIcon } from "lucide-react";
import { buttonVariants } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "cn";

export function DatePicker(props: { value?: Date; onValueChange?: (date: Date | undefined) => void; placeholder?: string; className?: string }) {
  const { value, onValueChange, placeholder = "Choose a date", className } = props;
  const controlled = Object.prototype.hasOwnProperty.call(props, "value");
  const [internalDate, setInternalDate] = React.useState<Date | undefined>(value);
  const date = controlled ? value : internalDate;

  function select(nextDate: Date | undefined) {
    if (!controlled) setInternalDate(nextDate);
    onValueChange?.(nextDate);
  }

  return (
    <Popover>
      <PopoverTrigger data-slot="button" data-variant="outline" data-size="default" className={cn(buttonVariants({ variant: "outline" }), "justify-start font-normal", className)}>
        <CalendarIcon />
        {date ? date.toLocaleDateString(undefined, { dateStyle: "long" }) : placeholder}
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar mode="single" selected={date} onSelect={select} defaultMonth={date} />
      </PopoverContent>
    </Popover>
  );
}

import * as React from "react";
import { cn } from "cn";

export function TypographyH1({ className, ...props }: React.ComponentProps<"h1">) { return <h1 className={cn("scroll-m-20 text-4xl font-semibold tracking-tight", className)} {...props} />; }
export function TypographyH2({ className, ...props }: React.ComponentProps<"h2">) { return <h2 className={cn("scroll-m-20 border-b pb-2 text-3xl font-semibold tracking-tight", className)} {...props} />; }
export function TypographyP({ className, ...props }: React.ComponentProps<"p">) { return <p className={cn("leading-7 [&:not(:first-child)]:mt-6", className)} {...props} />; }
export function TypographyLead({ className, ...props }: React.ComponentProps<"p">) { return <p className={cn("text-xl text-muted-foreground", className)} {...props} />; }
export function TypographyBlockquote({ className, ...props }: React.ComponentProps<"blockquote">) { return <blockquote className={cn("mt-6 border-l-2 pl-6 italic", className)} {...props} />; }
export function TypographyCode({ className, ...props }: React.ComponentProps<"code">) { return <code className={cn("rounded bg-muted px-1.5 py-0.5 font-mono text-sm font-medium", className)} {...props} />; }
